            const url = tr.contentUrl || tr.url;
            items.push({name: tr.name, url, id: (url||'').match(/music\/(\d+)/)?.[1]});
          }
        }
      }
    } catch(e) {}
  }
  return JSON.stringify(items.filter(i => i.name).slice(0,60));
})()

