def title_class(lines: list[str]) -> str:
    n = max((len(s) for s in lines), default=0)
    if n >= 8:
        return "chars8"
    if n >= 7:
        return "chars7"
    if n >= 6:
        return "chars6"
    if n >= 5:
        return "chars5"
    return ""

